+struct MultiConvertArgs {
+  const float* input[kMaxTensorsPerKernel];
+  uint8_t* output[kMaxTensorsPerKernel];
+  uint32_t rows[kMaxTensorsPerKernel];
+  uint32_t cols[kMaxTensorsPerKernel];
